  open: { name: 'Open track', size: 0.9, decay: 0.34, damp: 3200, mix: 0.1, early: 0.18, predelay: 0 },
  cabin: { name: 'Cabin', size: 0.5, decay: 0.3, damp: 2400, mix: 0.16, early: 0.26, predelay: 0 },
  pitlane: { name: 'Pit lane', size: 1.7, decay: 0.62, damp: 3000, mix: 0.24, early: 0.28, predelay: 4 },
  garage: { name: 'Garage', size: 1.15, decay: 0.72, damp: 2100, mix: 0.34, early: 0.32, predelay: 6 },
  tunnel: { name: 'Tunnel', size: 3.1, decay: 0.86, damp: 4200, mix: 0.46, early: 0.22, predelay: 8 },
  canyon: { name: 'Canyon', size: 5.2, decay: 0.8, damp: 2600, mix: 0.38, early: 0.24, predelay: 12 },
  hall: { name: 'Concert hall', size: 4.2, decay: 0.88, damp: 1800, mix: 0.3, early: 0.3, predelay: 16 },
