      const x = f.x + f.nx * lateral;
      const z = f.z + f.nz * lateral;
      const heading = Math.atan2(f.tx, f.tz);

      const p = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.7, 0.1), post);
      p.position.set(x, 0.85, z);
      p.castShadow = true;
      g.add(p);

