  const cfg = track.cfg;
  const g = new THREE.Group();
  g.name = 'scenery';

  const edge = cfg.halfWidth + cfg.kerbWidth + cfg.runoffWidth;

  g.add(buildBarrier(sp, edge + 1.8));
  g.add(buildBarrier(sp, -(edge + 1.8)));
