    // --- body ------------------------------------------------------------
    const body = root.getObjectByName(MODEL.body);
    if (!body || !body.isMesh) throw new Error('external car: body mesh missing');
    body.scale.copy(scale);
    body.position.set(0, 0, shiftZ);
    this.body.add(body);
