    addWheel(
      MODEL.fr,
      MODEL.frCentre,
      new THREE.Vector3(-halfTrack, wheelY, a),
      true,
      -1
    );
    // Rear wheels share one mesh; one axle spin group turns them together
    // (they run at the same omegaR anyway).
