    c.font = `${12 * k}px ${FONT}`;
    c.fillStyle = DIM;
    c.fillText('km/h', cx, cy + 22 * k);

    c.font = `600 ${26 * k}px ${FONT}`;
    c.fillStyle = ACCENT;
    c.fillText(t.gear, cx, cy - 34 * k);
